typedef struct { _Atomic(Block*) central; Block *local; int node; } Allocator;

void* malloc64(Allocator *A){
  Block *b = A->local; if(b){ A->local = b->next; return (void*)b; }
  Block *c = atomic_load_explicit(&A->central, memory_order_acquire);
  if(c){ atomic_store_explicit(&A->central, c->next, memory_order_release); return (void*)c; }
